def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]

    def fill_lines(line_key):
        clues = {}
        for r in range(n):
            for c in range(len(grid[r])):
                value = grid[r][c]
                if value:
                    key = line_key(r, c)
                    if key in clues and clues[key] != value:
                        return None
                    clues[key] = value
        if not clues:
            return None
        for period in range(1, n + 1):
            compatible = all(len({value for key, value in clues.items()
                                  if key % period == residue}) <= 1
                             for residue in range(period))
            complete = all(any(key % period == residue for key in clues)
                           for residue in range(period))
            if compatible and complete:
                sequence = {residue: next(value for key, value in clues.items()
                                          if key % period == residue)
                            for residue in range(period)}
                for r in range(n):
                    for c in range(len(grid[r])):
                        if grid[r][c] == 0:
                            out[r][c] = sequence[line_key(r, c) % period]
                return out
        return None

    # First identify horizontal bands: each nonempty row has a single color.
    row_colors = []
    row_mode = True
    for row in grid:
        colors = set(row) - {0}
        if len(colors) > 1:
            row_mode = False
            break
        row_colors.append(next(iter(colors)) if colors else 0)
    if row_mode:
        clues = {r: value for r, value in enumerate(row_colors) if value}
        for period in range(1, n + 1):
            compatible = all(len({value for r, value in clues.items()
                                  if r % period == residue}) <= 1
                             for residue in range(period))
            complete = all(any(r % period == residue for r in clues)
                           for residue in range(period))
            if compatible and complete:
                sequence = {residue: next(value for r, value in clues.items()
                                          if r % period == residue)
                            for residue in range(period)}
                for r in range(n):
                    if row_colors[r] == 0:
                        out[r] = [sequence[r % period]] * len(grid[r])
                return out

    for line_key in (lambda r, c: c - r, lambda r, c: r + c):
        result = fill_lines(line_key)
        if result is not None:
            return result
    return out

